do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'bib-102';
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,1,3,0,0,2,1,0,0,2,3,2,3,0,3,2,1,2,1}'::int[], array[$j$The New Testament has twenty seven books, from Matthew to Revelation.$j$,$j$The four Gospels are Matthew, Mark, Luke and John.$j$,$j$Jesus was born in Bethlehem, as Matthew 2 and Luke 2 record.$j$,$j$Jesus rose again the third day according to the scriptures.$j$,$j$Jesus said, Ye shall receive power, after that the Holy Ghost is come upon you.$j$,$j$Peter told them to repent and be baptized in the name of Jesus Christ for the remission of sins.$j$,$j$Stephen was stoned after he preached to the council in Acts 7.$j$,$j$Saul met the risen Jesus and became the apostle Paul.$j$,$j$Acts 11:26 says the disciples were called Christians first in Antioch.$j$,$j$The wages of sin is death, but the gift of God is eternal life through Jesus Christ our Lord.$j$,$j$The greatest of these is charity, which means love.$j$,$j$Paul taught that a person is justified by faith in Jesus Christ and not by the law.$j$,$j$For by grace are ye saved through faith; and that not of yourselves: it is the gift of God.$j$,$j$Philippians is full of joy and rejoicing, though Paul wrote it from prison.$j$,$j$All scripture is given by inspiration of God, and is profitable for doctrine, for reproof, for correction, for instruction in righteousness.$j$,$j$Hebrews 11:1 defines faith as the substance of things hoped for, the evidence of things not seen.$j$,$j$James taught that faith without works is dead also.$j$,$j$First John 4:8 says, God is love.$j$,$j$Jesus stands at the door and knocks, and He comes in to anyone who opens.$j$,$j$God shall wipe away all tears from their eyes, and the former things are passed away.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: New Testament Survey$j$ on conflict (item_id) do nothing;
end
$seed$;
